# -*- coding: utf-8 -*-
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ai_trader.journal import Journal
L = json.loads(r'''["第 96 轮列了三个还没量的乐观来源，其中一个是「仓位规模差异」。","这轮去量它，结果量出了一个更根本的东西。","","=== 一、先否掉我自己的一个猜测 ===","","看板上 equity 71.77 / plan_notional 70.84，而配置里有 trend_min_notional 55.0。","我据此猜：权益跌到约 55.7U 以下就会永久开不出仓，","而策略实测最大回撤 46.1%（100U -> 53.9U），正好撞上。","","猜错了。读代码：_min_notional() 在现货模式下返回 5.0，","trend_min_notional=55 只用于永续。当前 exec_market=spot，那道墙根本不存在。","","=== 二、实测两侧的生死线（用生产代码 _trend_plan 二分出来的）===","","    市场   一手                最小名义   生死线        100U 使用率","    现货   0.00001 BTC = 0.78U   5U        5.5U          99.5%","    永续   0.001 BTC = 77.75U   55U        77.9U         77.7%","","现货在不同价格下的生死线：30000 -> 5.2U，77749 -> 5.5U，120000 -> 6.1U。","","=== 三、真正的发现：永续在 100U 上不是「更贵」，是「做不了」 ===","","永续一手 0.001 BTC 按 77749 算是 77.75U，占 100U 账户的 78%。","生死线 77.9U 意味着：100U 回撤 22% 就永久无法建仓。","而策略实测最大回撤是 46.1%（100U -> 53.9U）——","它会在到达历史最差回撤之前就彻底停摆。","","而且 60U 时的失败原因还不是「名义不足」，是「数量取整后为 0」——","两种不同的失效，都不会报错，只是永远不成交。","","所以 100U 用现货，真正的理由是手数，不是资金费率。","HANDOFF 之前记的是「资金费 11.46%/年 vs 6.22%/年」——那是第二位的。","更根本的是：永续一手吃掉 78% 的账户，100U 根本没法正常做仓位管理。","这个理由更站得住，也更不容易被将来的自己推翻。","","=== 四、把它做成会自己叫的检查 ===","","这种失效不报错、不告警，只是永远不成交。「系统活着但死了」是最难发现的状态。","","所以给 preflight_live.py（切 live 前必跑的体检）加了「回撤余量」：","","    [GO  ] 权益 1275U，跌到 5.44U 才永久停摆（余量 100% >= 实测最大回撤 46.1%）","    [WARN] 权益 6U，跌到 5.44U 就永久开不出仓（余量仅 9%）","    [NO-GO] 权益为 0，谈不上余量","","阈值取 46.1%（策略在 6.84 年权威数据上的实测最大回撤）：","余量得能盖住自己历史最差的回撤，否则就是在最差行情里彻底停摆。","","=== 五、这一轮的自我批评（两次）===","","第一次：我差点只加了检查、没有任何测试逼它报警。","那样最危险——它让人以为有人守着。","补了 tests/test_preflight_headroom.py：好账户必须 GO、6U 必须 WARN、","0U 必须 NO-GO 且这一行不能消失。5 条变异全部变红。","","第二次：零权益那条测试我一开始写宽了，允许 OK/WARN/BAD 任意一种。","结果「把零权益分支删掉」这个变异活下来了：","代码会掉进 elif 分支算 1 - floor/0，ZeroDivisionError 被外层兜成 WARN「算不出」，","测试照样绿。但那时报告的是一句含糊的「算不出」，而不是「你没钱」。","运维要看到后者。收紧成必须 NO-GO 之后才红。","","又一次印证：宽一点的断言不只是「不够严」，它会具体地放过某一类缺陷。","","=== 六、验证 ===","","全量 483 条全绿（475 -> 483）。","新增 tests/test_account_floor.py（4 条）与 tests/test_preflight_headroom.py（4 条）。","","账户仍未到账（现货 USDT = 0）——所以真跑 preflight 时「回撤余量」行是 NO-GO，这是对的。"]''')
meta = json.loads(r'''{"round":97,"theme":"100U 账户的生死线：不是资金费率，是手数","hypothesis_wrong":"以为 trend_min_notional=55 在现货也生效会造成 55.7U 悬崖；实际 _min_notional() 现货返回 5.0","measured_floor":{"spot_77749":"5.5U","spot_30000":"5.2U","spot_120000":"6.1U","perp_77749":"77.9U"},"key_finding":"永续一手 77.75U = 100U 的 78%；回撤 22% 即永久停摆，而实测最大回撤 46.1%","reframing":"100U 用现货的根本理由是手数，资金费率是第二位","new_check":"preflight_live.py 增加「回撤余量」，阈值 46.1%","self_criticism":["差点只加检查不加测试——那会让人以为有人守着","零权益测试写宽（接受 OK/WARN/BAD），放过「删掉零权益分支」变异"],"lessons":"宽一点的断言不只是不够严，它会具体地放过某一类缺陷","tests_total":483,"new_tests":["tests/test_account_floor.py (4)","tests/test_preflight_headroom.py (4)"],"mutation":{"account_floor":"5 条中 1 条存活（手续费缓冲归零）→ 补「名义+费 <= 权益」断言后全红","preflight":"5 条全红（含收紧零权益断言后）"},"account_state":{"spot_usdt":0}}''')
J = Journal('data/market_trade.db')
J.start()
J.add('info', u'100U 账户的生死线：不是资金费率，是手数（永续一手吃掉 78% 账户）',
      chr(10).join(L), json.dumps(meta, ensure_ascii=False))
